/// <reference path="../typings-local/index.d.ts" />

import { BeSkill } from '@be/be-framework';
import jibo = require('jibo');
import * as net from 'net';

interface Command {
  type: 'text' | 'eye' | 'emoji' | 'torso' | 'light' | 'clear';
  timestamp?: number;
  delay?: number;
  data: any;
}

class DancePuppeteer extends BeSkill {
  private server: net.Server | null = null;
  private port: number = 25500;
  private overlay: HTMLElement | null = null;
  private statusDiv: HTMLElement | null = null;
  private textDisplay: HTMLElement | null = null;
  private commandQueue: Command[] = [];
  private isProcessing: boolean = false;
  private exiting: boolean = false;
  private screenGestureHandler: any = null;

  constructor(assetPack?: any) {
    super(assetPack);
    this.log.info('DancePuppeteer skill constructed');
  }

  public postInit(done: () => any): void {
    done();
  }

  public preload(done: (err?: any) => void): void {
    const es: any = (jibo as any).embodied && (jibo as any).embodied.speech;
    if (es && es.installDelegate) { es.installDelegate(this.assetPack); }
    done();
  }

  public open(result?: any): void {
    this.exiting = false;
    this.subscribeSwipeDown();

    try {
      const banner = document.getElementById('menu-redirect-banner');
      if (banner && banner.parentNode) { banner.parentNode.removeChild(banner); }
    } catch (e) { /* no-op */ }

    // Get DOM elements
    this.overlay = document.getElementById('overlay');
    this.statusDiv = document.getElementById('status');
    this.textDisplay = document.getElementById('text-display');
    
    // Start server after a short delay to allow UI to paint
    const self = this;
    setTimeout(() => {
      try {
        self.startServer();
        if (self.statusDiv) {
          self.statusDiv.textContent = 'Dance Puppeteer Ready\nListening on port 25500';
          setTimeout(() => {
            if (self.overlay) {
              self.overlay.style.display = 'none';
            }
          }, 2000);
        }
      } catch (err) {
        console.error('[dance-puppeteer] open failed:', err);
      }
    }, 50);
  }

  public close(done: () => void): void {
    this.unsubscribeSwipeDown();
    
    // Stop server
    if (this.server) {
      try { this.server.close(); } catch (e) { /* no-op */ }
      this.server = null;
    }
    
    // Clear command queue
    this.commandQueue = [];
    this.isProcessing = false;
    
    // Clear displays
    if (this.textDisplay) {
      this.textDisplay.textContent = '';
    }
    
    // Restore eye state
    this.restoreEyeState();
    
    done();
  }

  protected subscribeSwipeDown(): void {
    try {
      const shared: any = (jibo as any).globalEvents && (jibo as any).globalEvents.shared;
      if (!shared || !shared.screenGesture) { return; }
      this.screenGestureHandler = (gesture: string) => {
        if (String(gesture).toLowerCase() !== 'swipedown' || this.exiting) { return; }
        this.exiting = true;
        (this as any).exit();
      };
      shared.screenGesture.on(this.screenGestureHandler);
    } catch (err) { /* no-op */ }
  }

  protected unsubscribeSwipeDown(): void {
    if (!this.screenGestureHandler) { return; }
    try {
      const shared: any = (jibo as any).globalEvents && (jibo as any).globalEvents.shared;
      if (shared && shared.screenGesture) {
        shared.screenGesture.removeListener(this.screenGestureHandler);
      }
    } catch (err) { /* no-op */ }
    this.screenGestureHandler = null;
  }

  private startServer(): void {
    this.server = net.createServer((socket) => {
      this.log.info('Client connected from', socket.remoteAddress);
      
      socket.on('data', (data) => {
        try {
          const message = data.toString('utf-8').trim();
          this.log.info('Received command:', message);
          this.processCommand(message);
          socket.write('OK\n');
        } catch (err) {
          this.log.error('Error processing command:', err);
          socket.write('ERROR\n');
        }
      });
      
      socket.on('end', () => {
        this.log.info('Client disconnected');
      });
      
      socket.on('error', (err) => {
        this.log.error('Socket error:', err);
      });
    });
    
    this.server.listen(this.port, '0.0.0.0', () => {
      this.log.info(`Dance Puppeteer server listening on port ${this.port}`);
    });
    
    this.server.on('error', (err) => {
      this.log.error('Server error:', err);
    });
  }

  private processCommand(message: string): void {
    try {
      const command: Command = JSON.parse(message);
      
      // Add timestamp if not provided
      if (!command.timestamp) {
        command.timestamp = Date.now();
      }
      
      // Queue command for processing
      this.commandQueue.push(command);
      
      // Process queue if not already processing
      if (!this.isProcessing) {
        this.processQueue();
      }
    } catch (err) {
      this.log.error('Failed to parse command:', err);
    }
  }

  private processQueue(): void {
    if (this.commandQueue.length === 0) {
      this.isProcessing = false;
      return;
    }
    
    this.isProcessing = true;
    const command = this.commandQueue.shift()!;
    
    // Calculate delay if specified
    let delay = command.delay || 0;
    if (command.timestamp) {
      const now = Date.now();
      const scheduledTime = command.timestamp;
      if (scheduledTime > now) {
        delay = scheduledTime - now;
      }
    }
    
    setTimeout(() => {
      this.executeCommand(command);
      this.processQueue();
    }, delay);
  }

  private executeCommand(command: Command): void {
    this.log.info('Executing command:', command.type, command.data);
    
    switch (command.type) {
      case 'text':
        this.showText(command.data);
        break;
      case 'eye':
        this.manipulateEye(command.data);
        break;
      case 'emoji':
        this.showEmoji(command.data);
        break;
      case 'torso':
        this.setTorsoDirection(command.data);
        break;
      case 'light':
        this.setLightRing(command.data);
        break;
      case 'clear':
        this.clearDisplay();
        break;
      default:
        this.log.warn('Unknown command type:', command.type);
    }
  }

  private showText(data: any): void {
    if (!this.textDisplay) return;
    
    const text = data.text || '';
    const duration = data.duration || 0;
    
    this.textDisplay.textContent = text;
    this.textDisplay.style.display = 'block';
    
    if (duration > 0) {
      setTimeout(() => {
        this.textDisplay!.textContent = '';
      }, duration);
    }
  }

  private manipulateEye(data: any): void {
    try {
      const face = (jibo as any).face;
      const eye = face && face.eye;
      if (!eye) {
        this.log.warn('Eye API not available');
        return;
      }
      
      // Eye glow control
      if (data.glow !== undefined) {
        if (data.glow.enabled !== undefined) {
          eye.glow.enabled = data.glow.enabled;
        }
        if (data.glow.amount !== undefined) {
          eye.glow.amount = data.glow.amount;
        }
        if (data.glow.color !== undefined) {
          eye.glow.color = data.glow.color;
        }
      }
      
      // Eye alpha/visibility
      if (data.alpha !== undefined) {
        eye.eye.alpha = data.alpha;
      }
      
      // Look at direction
      if (data.lookAt) {
        const lookAt = data.lookAt;
        if (lookAt.x !== undefined || lookAt.y !== undefined || lookAt.z !== undefined) {
          // Use expression API for looking
          const THREE = require('@jibo/three');
          const target = new THREE.Vector3(
            lookAt.x || 0,
            lookAt.y || 0,
            lookAt.z || 0
          );
          jibo.expression.acquireTarget({ position: target }).catch((err: any) => {
            this.log.warn('Failed to set look direction:', err);
          });
        }
      }
      
    } catch (err) {
      this.log.error('Error manipulating eye:', err);
    }
  }

  private showEmoji(data: any): void {
    try {
      const emojiName = data.emoji || '';
      const duration = data.duration || 2000;
      
      if (!emojiName) {
        this.log.warn('No emoji name provided');
        return;
      }
      
      // Play emoji animation via animDB
      const query = {
        name: emojiName,
        layers: 'screen'
      };
      
      const result = jibo.animDB.query(query);
      if (result.matching.length > 0) {
        const anim = result.matching[0];
        anim.play({ cache: jibo.loader.activeCache }).result.then(() => {
          if (duration > 0) {
            setTimeout(() => {
              // Animation will naturally end
            }, duration);
          }
        }).catch((err: any) => {
          this.log.warn('Failed to play emoji animation:', err);
        });
      } else {
        this.log.warn('Emoji animation not found:', emojiName);
      }
      
    } catch (err) {
      this.log.error('Error showing emoji:', err);
    }
  }

  private setTorsoDirection(data: any): void {
    try {
      const yaw = data.yaw || 0;
      const pitch = data.pitch || 0;
      const roll = data.roll || 0;
      
      // Use animation database for body movements
      // Look for animations that match the desired direction
      const query = {
        cat: 'body',
        filter: `yaw:${yaw},pitch:${pitch}`
      };
      
      const result = jibo.animDB.query(query);
      if (result.matching.length > 0) {
        const anim = result.matching[0];
        anim.play({ cache: jibo.loader.activeCache }).catch((err: any) => {
          this.log.warn('Failed to play torso animation:', err);
        });
      } else {
        // Try generic body animations
        const genericQuery = {
          cat: 'body'
        };
        const genericResult = jibo.animDB.query(genericQuery);
        if (genericResult.matching.length > 0) {
          const anim = genericResult.matching[Math.floor(Math.random() * genericResult.matching.length)];
          anim.play({ cache: jibo.loader.activeCache }).catch((err: any) => {
            this.log.warn('Failed to play generic body animation:', err);
          });
        }
      }
      
    } catch (err) {
      this.log.error('Error setting torso direction:', err);
    }
  }

  private setLightRing(data: any): void {
    try {
      const face = (jibo as any).face;
      const eye = face && face.eye;
      if (!eye) {
        this.log.warn('Eye API not available for light ring');
        return;
      }
      
      const color = data.color || '#ffffff';
      const enabled = data.enabled !== undefined ? data.enabled : true;
      const amount = data.amount !== undefined ? data.amount : 1;
      
      eye.glow.enabled = enabled;
      eye.glow.amount = amount;
      eye.glow.color = color;
      
    } catch (err) {
      this.log.error('Error setting light ring:', err);
    }
  }

  private clearDisplay(): void {
    if (this.textDisplay) {
      this.textDisplay.textContent = '';
    }
    this.restoreEyeState();
  }

  private restoreEyeState(): void {
    try {
      const face = (jibo as any).face;
      const eye = face && face.eye;
      if (eye) {
        eye.glow.enabled = false;
        eye.glow.amount = 0;
        eye.eye.alpha = 1;
      }
    } catch (err) {
      this.log.error('Error restoring eye state:', err);
    }
  }
}

export = DancePuppeteer;
